const ev = {};
for (const i of $input.all()) ev[i.json.slug] = {name: i.json.name, market: i.json.market, city: i.json.city, date_label: i.json.date_label};
return [{json: {ev}}];

// EDIT ME: one sentence on what your company does. It is used in the outreach text below.
const PITCH_EN = 'YOUR_COMPANY builds AI that handles order and invoice exceptions inside ERP systems like SAP and Oracle, so your team only sees the cases that need a person.';
const PITCH_DE = 'YOUR_COMPANY baut KI, die Ausnahmen bei Bestellungen und Rechnungen direkt im ERP wie SAP oder Oracle bearbeitet. Ihr Team sieht nur noch die Fälle, die eine Person braucht.';
const ev = $('Pack').first().json.ev;
const RULE = {
  DE: 'LinkedIn note first. No cold email in Germany (UWG section 7). Phone only after the reviewer records a concrete topical reason the person would expect this call (BVerwG 29 Jan 2025, 6 C 3/23). A job title or a public listing alone is not enough. Lawyer sign-off pending.',
  UK: 'Email to a corporate address is possible (PECR). Name the sender, add an opt-out, check TPS/CTPS before any call.',
  US: 'Email is possible (CAN-SPAM). Name the sender, add a postal address and an opt-out.'
};
const FN = {'procurement': 'procurement', 'supply chain': 'supply chain', 'finance ops': 'finance operations', 'operations or IT': 'operations'};
const SAP = {
  ap: {process: 'procure-to-pay', tcodes: ['MIRO', 'MIGO', 'OMR6', 'MR11'], pain: 'Invoices blocked in MIRO when price or quantity differs from the PO or the goods receipt (payment block reason R), and a GR/IR clearing account that has to be cleaned up at close.'},
  purchasing: {process: 'procure-to-pay', tcodes: ['ME21N', 'MIRO', 'OMR6'], pain: 'Price and quantity variances between the PO (ME21N) and the invoice that break three-way matching, and the tolerance limits (OMR6) that decide what gets blocked.'},
  goods: {process: 'procure-to-pay', tcodes: ['MIGO', 'VL01N', 'MIRO'], pain: 'Goods receipt (MIGO) discrepancies against the PO or the delivery that leave the invoice unmatched.'},
  o2c: {process: 'order-to-cash', tcodes: ['VA01', 'VL01N', 'VKM1'], pain: 'Sales orders held in VA01 by credit or delivery blocks, and orders that stall between delivery (VL01N) and billing.'},
  close: {process: 'procure-to-pay', tcodes: ['MR11', 'F.13', 'MIRO'], pain: 'GR/IR clearing account balances (MR11) that finance has to explain at month end.'},
  it: {process: 'both', tcodes: ['OMR6', 'MIRO', 'VA01'], pain: 'Exception rules and tolerance keys (OMR6) that sit in SAP configuration and need a safe way to automate around them.'}
};
const ROUTE = {
  A: {depth: 'full', apollo_company_lookup: true, hiring_scan: true, contact_waterfall: 'premium, planned'},
  B: {depth: 'standard', apollo_company_lookup: true, hiring_scan: false, contact_waterfall: 'single provider, planned'},
  C: {depth: 'none', apollo_company_lookup: false, hiring_scan: false, contact_waterfall: 'none, ESI level 5 spends zero credits'}
};
const WF_FULL = {status: 'planned, not running', credit_cap: 15, steps: [
  {n: 1, provider: 'Apollo people match', input: 'name and company domain', run_if: 'always', stop_if: 'email status is valid'},
  {n: 2, provider: 'Cognism', input: 'name and company domain', run_if: 'no valid email yet and the market is DE or UK', stop_if: 'email status is valid'},
  {n: 3, provider: 'Datagma', input: 'name and company, or the LinkedIn URL if the reviewer added one', run_if: 'still no valid email', stop_if: 'email status is valid'},
  {n: 4, provider: 'Email verifier', input: 'any email that was found', run_if: 'an email exists and is not verified yet', stop_if: 'valid is accepted, risky is held, invalid moves on to the next provider'}
], write_back: 'save_contact: email, source provider and status', phone: 'only after a valid email, and never for DE until the call basis is recorded'};
const WF_ONE = {status: 'planned, not running', credit_cap: 3, steps: [
  {n: 1, provider: 'Apollo people match', input: 'name and company domain', run_if: 'always', stop_if: 'email status is valid'},
  {n: 2, provider: 'Email verifier', input: 'any email that was found', run_if: 'an email exists and is not verified yet', stop_if: 'valid is accepted, anything else is held'}
], write_back: 'save_contact: email, source provider and status', phone: 'none'};
const ESI_TABLE = {
  2: {label: 'Emergent', gtm: 'Tier A champion with a live hiring signal', apollo_calls_max: 2, ai_research: true, waterfall: WF_FULL, spend: 'Highest priority. Top-tier providers and AI drafting first (planned).'},
  3: {label: 'Urgent', gtm: 'Tier A champion or economic buyer', apollo_calls_max: 2, ai_research: true, waterfall: WF_FULL, spend: 'Standard waterfall with a spend cap per account (planned cap: 15 credits).'},
  4: {label: 'Non-urgent, one resource', gtm: 'Tier B account with a generic fit', apollo_calls_max: 1, ai_research: false, waterfall: WF_ONE, spend: 'Single provider only. No AI agent research.'},
  5: {label: 'No resources', gtm: 'Tier C or X: junior, operations or out of scope', apollo_calls_max: 0, ai_research: false, waterfall: null, spend: 'Zero API credits. The CRM payload keeps the name only.'}
};
const ESI_LEVEL = {A: 3, B: 4, C: 5, X: 5};
function esiFor(tier) {
  const level = ESI_LEVEL[tier] || 5;
  return {scale: 'Emergency Severity Index (Wuerz and Eitel)', level, ...ESI_TABLE[level], level_1: 'not used, there is no inbound intent in an event pipeline', level_2_rule: 'a tier A lead moves up to level 2 when the hiring scan finds finance, procurement or ERP roles'};
}
function acctKey(name) {
  return String(name || '').toLowerCase().replace(/&/g, ' and ').replace(/\b(gmbh|mbh|ag|se|kg|kgaa|co|inc|llc|ltd|plc|corp|corporation|group|holding|company|sa|nv|bv|ohg|limited)\b\.?/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim().replace(/ /g, '-');
}
function sapFor(title, fn) {
  const t = String(title || '');
  if (/payable|kreditor|invoic|rechnung|shared service|\bgbs\b|business services|\bp2p\b|procure[- ]to[- ]pay|\bap\b/i.test(t)) return SAP.ap;
  if (/order[- ]to[- ]cash|\bo2c\b|order management|billing|credit|collections|receivable|debitor|auftrag|\bar\b/i.test(t)) return SAP.o2c;
  if (fn === 'procurement') return SAP.purchasing;
  if (fn === 'supply chain') return SAP.goods;
  if (fn === 'finance ops') return SAP.close;
  return SAP.it;
}
return $input.all().filter(i => i.json && i.json.id).map(i => {
  const l = i.json;
  const e = ev[l.event_slug] || {};
  const market = e.market || 'US';
  const parts = String(l.full_name).trim().split(/\s+/);
  const first = parts[0];
  const last = parts.slice(1).join(' ');
  const sd = l.score_detail || {};
  const s = sapFor(l.title, sd.function);
  const sapp = {process: s.process, tcodes: s.tcodes, hypothesis: s.pain, basis: 'Role-based hypothesis from title and function. The ERP in use and the real pain at this account are not verified.', committee_role: sd.role || null};
  const callBasis = market === 'DE'
    ? {required: true, status: 'blocked_until_evidence', topical_link: null, hint: 'Find a concrete public link between this person and ' + s.process + ' exceptions (session abstract, talk, post) and record it before any call task exists.', rule: 'BVerwG 29 Jan 2025, 6 C 3/23: a business call needs at least presumed consent, shown by a concrete interest of the recipient in the offer. Lawyer sign-off pending.', recorded_by: null, recorded_at: null}
    : {required: false, status: 'not_required', rule: 'No call rule beyond the market rule in channel_rule.'};
  const prior = /edition/i.test(l.source_kind || '');
  const ed = ((String(l.source_kind || '').match(/\((\d{4}) edition\)/)) || [])[1];
  const evName = String(l.event_name || '').replace(/\s*\(BME\)\s*$/, '');
  const de = market === 'DE';
  const opener = de
    ? 'Guten Tag ' + first + ' ' + last + ', ich habe gesehen, dass Sie ' + (prior && !ed ? 'beim letzten ' : 'beim ') + evName + (prior ? (ed ? ' ' + ed : '') + ' gesprochen haben' : ' als Sprecher dabei sind') + '. ' + PITCH_DE + ' Wenn das bei ' + l.company + ' ein Thema ist, zeige ich gern kurz, wie andere Teams das lösen. Haben Sie Zeit für ein kurzes Gespräch?'
    : 'Hi ' + first + ', I saw you ' + (prior ? (ed ? 'spoke at the ' + ed + ' edition of ' : 'spoke at last year\'s ') : 'are on the speaker list for ') + evName + '. ' + PITCH_EN + ' If that is a pain point at ' + l.company + ', I would be glad to share how other teams approach it. Open to a short call?';
  const note = l.full_name + ', ' + l.title + ' at ' + l.company + '. ' + (prior ? 'Listed as a speaker at the previous edition of ' : 'Listed as a speaker at ') + l.event_name + ' (' + (prior ? 'next edition ' : '') + (e.date_label || 'date n/a') + ', ' + (e.city || 'city n/a') + '). Why it fits: ' + (sd.path || 'n/a') + '. Source: ' + l.source_url + '. Likely SAP angle (hypothesis from the role, not verified): ' + sapp.hypothesis + ' T-codes: ' + sapp.tcodes.join(', ') + '. Not known yet: work email, ERP in use, whether this person owns the exception workload. Next step: confirm the role on the source page, then find the person in Sales Navigator (manual).';
  const esi = esiFor(l.tier);
  const incumbent_hypothesis = sd.competitor_host ? {basis: 'The event host sells overlapping software, so this account may already use it.', stance: 'Treat it as a contract-expiry trigger to research and a messaging input, not a disqualifier.', verified: false} : null;
  const enrichment = {
    version: 2, esi, incumbent_hypothesis, sap_pain: sapp, call_basis: callBasis, scoring: {node: sd.node || null, role: sd.role || null, path: sd.path || null}, route: ROUTE[l.tier] || ROUTE.C,
    draft_kind: 'template draft (the LLM step plugs in here)',
    research_note: note,
    opener,
    language: de ? 'de' : 'en',
    channel_rule: RULE[market] || RULE.US,
    apollo: {status: 'not_run', reason: 'No Apollo API key connected. Production: enrich approved leads only, best tier first.'},
    clay: {status: 'not_run', reason: 'No Clay table connected yet. Production: one row per approved lead.'},
    generated_at: new Date().toISOString()
  };
  const hubspot = {
    dry_run: true,
    note: 'Never sent. Contacts upsert on the unique property gm_lead_id, so no email is needed. Companies upsert on gm_account_key, and the Apollo domain is stored as a normal property.',
    dedupe: {
      contact: {object: 'contacts', idProperty: 'gm_lead_id', value: l.id, why: 'Unique custom property. HubSpot only dedupes contacts on email by default, and event leads have no email yet.', second_match: 'email, once enrichment finds one'},
      company: {object: 'companies', idProperty: 'gm_account_key', value: acctKey(l.company), why: 'Always known at approval. The Apollo domain is written as a normal property.', setup: 'Create both properties once as unique-value text properties before the first live write.'}
    },
    company: {object: 'companies', properties: {name: l.company, gm_account_key: acctKey(l.company), gm_erp_system: 'unverified'}},
    contact: {object: 'contacts', properties: {
      firstname: first, lastname: last, jobtitle: l.title, company: l.company,
      lifecyclestage: 'lead', hs_lead_status: 'NEW',
      gm_source_event: l.event_name, gm_source_url: l.source_url, gm_icp_tier: l.tier,
      gm_function: FN[sd.function] || null, gm_market: market, gm_lead_id: l.id, gm_committee_role: sd.role || null, gm_scoring_node: sd.node || null, gm_sap_process: sapp.process, gm_sap_tcodes: sapp.tcodes.join(';'), gm_sap_pain_hypothesis: sapp.hypothesis, gm_erp_system: 'unverified', gm_call_basis_status: callBasis.status, gm_enrichment_depth: (ROUTE[l.tier] || ROUTE.C).depth, gm_esi_level: esi.level
    }}
  };
  return {json: {lead_id: l.id, enrichment, hubspot, clay_row: {lead_id: l.id, full_name: l.full_name, title: l.title, company: l.company, event: l.event_name, market, tier: l.tier, source_url: l.source_url, opener, research_note: note, sap_process: sapp.process, sap_tcodes: sapp.tcodes.join(', '), committee_role: sd.role || null, esi_level: esi.level}}};
});

const b = $('Apollo merge').item.json;
const err = $json && $json.error;
const cfg = $('Config').first().json;
const clay = err
  ? {status: 'failed', reason: String(err.message || err).slice(0, 200)}
  : {status: 'sent', table: cfg.clay_table, sent_at: new Date().toISOString()};
return {json: {lead_id: b.lead_id, enrichment: {...b.enrichment, clay}, hubspot: b.hubspot, clay_url: err ? null : cfg.clay_table}};

const b = $('Build').item.json;
const tier = b.clay_row.tier;
const want = String(b.hubspot.company.properties.name || '');
const norm = s => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/\b(gmbh|mbh|ag|se|kg|kgaa|co|inc|llc|ltd|plc|corp|corporation|group|holding|company|sa|nv|bv|ohg|limited)\b\.?/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
if ($json.error || !$json.body) return {json: {tier, org: null, run_hiring: false, error: 'Apollo call failed: ' + String(($json.error && $json.error.message) || $json.error || 'no response').slice(0, 140)}};
if ($json.statusCode !== 200) return {json: {tier, org: null, run_hiring: false, error: 'Apollo returned status ' + $json.statusCode}};
const orgs = $json.body.organizations || [];
const w = norm(want);
let best = null, match = null;
for (const o of orgs) { const n = norm(o.name); if (n && n === w) { best = o; match = 'exact'; break; } }
if (!best) for (const o of orgs) { const n = norm(o.name); if (n && w && (n.startsWith(w + ' ') || w.startsWith(n + ' '))) { best = o; match = 'close'; break; } }
const org = best ? {id: best.id, name: best.name, primary_domain: best.primary_domain, industry: best.industry, estimated_num_employees: best.estimated_num_employees, organization_revenue_printed: best.organization_revenue_printed, linkedin_url: best.linkedin_url} : null;
return {json: {tier, org, match, reason: org ? null : (orgs.length ? 'No Apollo company matched the name closely enough.' : 'No Apollo result for this name.'), run_hiring: !!org && tier === 'A'}};

const b = $('Build').item.json;
if (b.enrichment.esi && b.enrichment.esi.apollo_calls_max === 0) {
  const skipped = {status: 'skipped', reason: 'ESI level 5 spends zero API credits, so no company lookup was made.', looked_up_at: new Date().toISOString()};
  const enr0 = {...b.enrichment, research_note: b.enrichment.research_note + ' Company lookup (Apollo): skipped. ESI level 5 spends zero credits.', apollo: skipped};
  return {json: {lead_id: b.lead_id, enrichment: enr0, hubspot: JSON.parse(JSON.stringify(b.hubspot)), clay_row: b.clay_row}};
}
const pick = $('Apollo pick').item.json;
const RELEVANT = /procure|purchas|sourcing|supply chain|accounts? (payable|receivable)|order[- ]to[- ]cash|procure[- ]to[- ]pay|\bp2p\b|\bo2c\b|financ|controll|billing|invoic|collections|\bsap\b|\berp\b|netsuite|shared service/i;
const ranHiring = !!($json && $json.body && Array.isArray($json.body.organization_job_postings));
let hiring = null;
if (ranHiring) {
  const posts = $json.body.organization_job_postings;
  const total = ($json.body.pagination && $json.body.pagination.total_entries) || posts.length;
  const rel = posts.filter(p => RELEVANT.test(p.title || ''));
  hiring = {status: 'ok', open_postings: total, scanned: posts.length, relevant_in_scan: rel.length, examples: rel.slice(0, 3).map(p => p.title)};
} else if (pick.org && pick.tier !== 'A') {
  hiring = {status: 'skipped', reason: 'Credits are reserved for tier A leads.'};
} else if (pick.org) {
  hiring = {status: 'failed', reason: 'The hiring lookup returned nothing.'};
}
const at = new Date().toISOString();
let apollo;
if (pick.org) {
  const o = pick.org;
  apollo = {status: 'ok', match: pick.match, company: o.name, domain: o.primary_domain || null, industry: o.industry || null, employees: o.estimated_num_employees || null, revenue: o.organization_revenue_printed || null, linkedin: o.linkedin_url || null, hiring, person_level: 'not available on the Apollo Free plan, so no email or phone', looked_up_at: at};
} else {
  apollo = {status: pick.error ? 'failed' : 'no_match', reason: pick.error || pick.reason || 'No match.', looked_up_at: at};
}
let add;
if (apollo.status === 'ok') {
  add = ' Company (Apollo, ' + apollo.match + ' match): ' + [apollo.domain, apollo.industry, apollo.employees ? apollo.employees + ' employees' : null, apollo.revenue ? 'revenue ' + apollo.revenue : null].filter(Boolean).join(', ') + '.';
  if (hiring && hiring.status === 'ok') add += ' Hiring: ' + hiring.open_postings + ' open roles' + (hiring.relevant_in_scan ? ', ' + hiring.relevant_in_scan + ' finance, procurement or ERP roles among the first ' + hiring.scanned + (hiring.examples.length ? ' (e.g. ' + hiring.examples.join('; ') + ')' : '') : ', none in finance, procurement or ERP among the first ' + hiring.scanned) + '.';
} else {
  add = ' Company lookup (Apollo): ' + apollo.reason;
}
let esi = b.enrichment.esi;
if (esi.level === 3 && hiring && hiring.status === 'ok' && hiring.relevant_in_scan > 0) esi = {...esi, ...{level: 2, label: 'Emergent', gtm: 'Tier A champion with a live hiring signal', upgraded_by: 'hiring scan found ' + hiring.relevant_in_scan + ' finance, procurement or ERP roles'}, apollo_calls_max: esi.apollo_calls_max};
const enrichment = {...b.enrichment, esi, research_note: b.enrichment.research_note + add, apollo};
const hubspot = JSON.parse(JSON.stringify(b.hubspot));
hubspot.note = 'Never sent. Contacts upsert on gm_lead_id and companies on gm_account_key, so no email is needed. The company domain comes from Apollo when the name matched.';
hubspot.contact.properties.gm_esi_level = esi.level;
if (apollo.status === 'ok') {
  if (apollo.domain) hubspot.company.properties.domain = apollo.domain;
  if (apollo.employees) hubspot.company.properties.numberofemployees = apollo.employees;
  hubspot.company.properties.gm_apollo_match = apollo.match;
}
const clay_row = {...b.clay_row, esi_level: esi.level, research_note: enrichment.research_note, company_domain: apollo.domain || null, company_employees: apollo.employees || null};
return {json: {lead_id: b.lead_id, enrichment, hubspot, clay_row}};
